import{_ as e,o as a,c as o,al as i}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"Test FW_02 - Full Autonomous","description":"","frontmatter":{},"headers":[],"relativePath":"zh/test_cards/fw_02_full_autonomous.md","filePath":"zh/test_cards/fw_02_full_autonomous.md"}'),l={name:"zh/test_cards/fw_02_full_autonomous.md"};function n(s,t,u,r,h,d){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="test-fw-02-full-autonomous" tabindex="-1">Test FW_02 - Full Autonomous <a class="header-anchor" href="#test-fw-02-full-autonomous" aria-label="Permalink to &quot;Test FW_02 - Full Autonomous&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>To test the auto modes such as Mission, Takeoff, Hold, and RTL for fixed wing vehicles.</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Plan a mission on the ground. Ensure the mission has:</p><ul><li>Takeoff as first waypoint</li><li>Changes in altitude throughout the mission</li><li>Last waypoint is an RTL</li><li>Duration of 1 to 2 minutes</li></ul><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ Takeoff</p><p>    ❏ Engage Takeoff mode (hand launch or runway)</p><p>    ❏ Vehicle should climb to takeoff altitude</p><p>    ❏ Vehicle should hold/loiter after reaching takeoff altitude</p><p>❏ Mission</p><p>    ❏ Auto takeoff (hand launch or runway)</p><p>    ❏ Verify changes in altitude throughout the mission</p><p>    ❏ Verify Mission Ends in RTL</p><p>    ❏ Duration of 1 to 2 minutes</p><p>    ❏ Auto land or hold at end</p><p>❏ Hold</p><p>    ❏ Engage Hold mode during flight</p><p>    ❏ Vehicle should orbit at current position and altitude</p><p>    ❏ Orbit radius and direction should match parameters</p><p>❏ RTL</p><p>    ❏ Arm and takeoff in any manual mode</p><p>    ❏ Fly out ~200m from start point</p><p>    ❏ Engage Return mode</p><p>    ❏ Vehicle should climb to RTL altitude if below it</p><p>    ❏ Vehicle should return to home and hold or land</p><h2 id="预期成果" tabindex="-1">预期成果 <a class="header-anchor" href="#预期成果" aria-label="Permalink to &quot;预期成果&quot;">​</a></h2><ul><li>任务应该在第一次尝试时上传</li><li>Vehicle should automatically takeoff upon engaging Auto</li><li>Waypoint tracking should be smooth with appropriate turn radius</li><li>Vehicle should adjust height to RTL altitude before returning home</li><li>Landing approach should be stable (if auto-land is configured)</li></ul>',29)])])}const c=e(l,[["render",n]]);export{f as __pageData,c as default};
